import { Component, HostListener, signal } from '@angular/core';
import { ManufacturersComponent } from './manufacturers.component';
import { RatingsComponent } from './ratings.component';
import { ReportsComponent } from './reports.component';
import { MessagesComponent } from './messages.component';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [ManufacturersComponent, RatingsComponent, ReportsComponent, MessagesComponent],
  template: `
    <div class="header"><div class="header-content">
      <strong class="title">CarStore</strong>
      <div id="gwt-debug-menubar" class="menubar">
        <a href="#manufacturer">Manufacturers</a>
        <a href="#rating">Ratings</a>
        <a href="#report">Reports</a>
      </div>
    </div></div>
    <app-messages />
    <main>
      @switch (page()) {
        @case ('rating') { <app-ratings /> }
        @case ('report') { <app-reports /> }
        @default { <app-manufacturers /> }
      }
    </main>
  `,
})
export class AppComponent {
  page = signal(this.read());
  @HostListener('window:hashchange') onHash() { this.page.set(this.read()); }
  private read() { return location.hash.replace(/^#\/?/, '').split(/[?;]/)[0] || 'manufacturer'; }
}
